package glitch

import data.glitch_lib

is_bucket_or_storage_type(t) {
    glitch_lib.contains(t, "bucket")
}

is_bucket_or_storage_type(t) {
    glitch_lib.contains(t, "storage")
}

is_cors_resource_type(t) {
    glitch_lib.contains(t, "cors")
}

has_cors_block(node) {
    walk(node, [_, n])
    n.ir_type == "Attribute"
    glitch_lib.contains(n.name, "cors")
}

is_relevant_resource(node) {
    is_cors_resource_type(node.type)
}

is_relevant_resource(node) {
    is_bucket_or_storage_type(node.type)
    has_cors_block(node)
}

is_origin_attr(name) {
    glitch_lib.contains(name, "origin")
}

value_has_wildcard(value) {
    value.ir_type == "Array"
    item := value.value[_]
    item.ir_type == "String"
    item.value == "*"
}

value_has_wildcard(value) {
    value.ir_type == "String"
    value.value == "*"
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    is_relevant_resource(node)

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    is_origin_attr(attr.name)
    value_has_wildcard(attr.value)

    result := {
        "type": "sec_s3_unsecured_cors",
        "element": attr,
        "path": parent.path,
        "description": "Insecure CORS Policy on Object Storage Bucket - Wildcard origin in CORS configuration allows unauthorized cross-origin requests, potentially exposing sensitive data or enabling cross-site attacks. (CWE-942)"
    }
}

